import csv
import math
import re
from datetime import datetime
from statistics import median

def parse_amount_str(s):
    if s is None:
        return float('nan')
    s = s.strip()
    if not s:
        return float('nan')

    is_negative = False
    if 'CR' in s.upper():
        is_negative = True
    if s.startswith('(') or '(' in s:
        is_negative = True
    if '-' in s:
        is_negative = True

    s = s.replace('C1', '').replace('C2', '')
    cleaned = re.sub(r'[^0-9,.]', '', s)

    if not cleaned:
        return float('nan')

    has_comma = ',' in cleaned
    has_dot = '.' in cleaned

    if has_comma and has_dot:
        last_comma = cleaned.rfind(',')
        last_dot = cleaned.rfind('.')
        if last_comma > last_dot:
            decimal_sep = ','
            cleaned = cleaned.replace('.', '')
            cleaned = cleaned.replace(',', '.')
        else:
            decimal_sep = '.'
            cleaned = cleaned.replace(',', '')
    elif has_comma:
        last_comma = cleaned.rfind(',')
        after_last = cleaned[last_comma + 1:]
        if len(after_last) == 2:
            cleaned = cleaned.replace(',', '.')
        else:
            cleaned = cleaned.replace(',', '')
    elif has_dot:
        last_dot = cleaned.rfind('.')
        after_last = cleaned[last_dot + 1:]
        if len(after_last) == 2:
            pass
        else:
            cleaned = cleaned.replace('.', '')

    if not cleaned:
        return float('nan')

    val = float(cleaned)
    if is_negative:
        val = -val
    return val


def parse_notes(notes):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if not notes:
        return items, adj_pct, fee, waive

    items_match = re.search(r'items=(\d+)', notes, re.IGNORECASE)
    if items_match:
        items = int(items_match.group(1))

    adj_match = re.search(r'ad j\s*=\s*([+-]?\d+(?:\.\d+)?)%', notes, re.IGNORECASE)
    if not adj_match:
        adj_match = re.search(r'ad j\s*=\s*([+-]?\d+(?:\.\d+)?)%', notes.replace(' ', ''), re.IGNORECASE)
    if not adj_match:
        adj_match = re.search(r'adj=([+-]?\d+(?:\.\d+)?)%', notes, re.IGNORECASE)
    if adj_match:
        adj_pct = float(adj_match.group(1))

    fee_match = re.search(r'fee=([+-]?\d+(?:\.\d+)?)', notes, re.IGNORECASE)
    if fee_match:
        fee = float(fee_match.group(1))

    waive_match = re.search(r'waive\s*=\s*true', notes, re.IGNORECASE)
    if waive_match:
        waive = True

    return items, adj_pct, fee, waive


def parse_event_time(et):
    if not et or not et.strip():
        return None
    et = et.strip()
    try:
        return datetime.strptime(et, '%Y-%m-%dT%H:%M:%S%z')
    except ValueError:
        try:
            return datetime.strptime(et, '%Y-%m-%dT%H:%M:%SZ')
        except ValueError:
            try:
                return datetime.strptime(et, '%Y-%m-%dT%H:%M:%S+00:00')
            except ValueError:
                return None


def answer() -> list[str]:
    rows = []
    with open('/app/dataset/data.csv', 'r', newline='') as f:
        reader = csv.reader(f)
        header = next(reader)
        for row_idx, row in enumerate(reader):
            record_id = row[0]
            event_time_str = row[1]
            region = row[2]
            channel = row[3].strip()
            amount_str = row[4]
            notes = row[5]

            evt = parse_event_time(event_time_str)

            base_amount = parse_amount_str(amount_str)
            items_val, adj_pct, fee_val, waive_val = parse_notes(notes)

            if math.isnan(base_amount):
                net = float('nan')
            else:
                net = base_amount * (1 + adj_pct / 100.0) + fee_val
                if waive_val:
                    net = 0.0

            rows.append({
                'record_id': record_id,
                'event_time': evt,
                'region': region,
                'channel': channel,
                'base_amount': base_amount,
                'items': items_val,
                'adj_pct': adj_pct,
                'fee': fee_val,
                'waive': waive_val,
                'net': net,
                'file_order': row_idx
            })

    # Deduplicate: keep one row per record_id
    # Choose latest event_time, tie-break: prefer real net, then earlier file_order
    deduped = {}
    for r in rows:
        rid = r['record_id']
        if rid not in deduped:
            deduped[rid] = r
            continue
        existing = deduped[rid]
        cur_et = r['event_time']
        ex_et = existing['event_time']
        if cur_et is not None and ex_et is not None:
            if cur_et > ex_et:
                deduped[rid] = r
            elif cur_et == ex_et:
                cur_has_net = not math.isnan(r['net'])
                ex_has_net = not math.isnan(existing['net'])
                if cur_has_net and not ex_has_net:
                    deduped[rid] = r
                elif cur_has_net == ex_has_net:
                    if r['file_order'] < existing['file_order']:
                        deduped[rid] = r
        elif cur_et is None and ex_et is None:
            cur_has_net = not math.isnan(r['net'])
            ex_has_net = not math.isnan(existing['net'])
            if cur_has_net and not ex_has_net:
                deduped[rid] = r
            elif cur_has_net == ex_has_net:
                if r['file_order'] < existing['file_order']:
                    deduped[rid] = r
        elif cur_et is not None and ex_et is None:
            deduped[rid] = r

    rows = list(deduped.values())

    # Filter: non-missing event_time, event_time between 2025-10-01 and 2025-12-31
    # channel != "phone" (case-insensitive), finite net
    start = datetime(2025, 10, 1, 0, 0, 0)
    end = datetime(2025, 12, 31, 23, 59, 59)

    filtered = []
    for r in rows:
        if r['event_time'] is None:
            continue
        if not (start <= r['event_time'] <= end):
            continue
        if r['channel'].lower() == 'phone':
            continue
        if not math.isfinite(r['net']):
            continue
        filtered.append(r)

    # Group by (region, month)
    groups = {}
    for r in filtered:
        month_key = r['event_time'].strftime('%Y-%m')
        key = (r['region'], month_key)
        if key not in groups:
            groups[key] = []
        groups[key].append(r)

    # Compute robust z-scores within each group
    for key, grp in groups.items():
        nets = [r['net'] for r in grp]
        med = median(nets)
        abs_devs = [abs(n - med) for n in nets]
        mad = median(abs_devs)

        for r in grp:
            if mad == 0:
                robust_z = 0.0
            else:
                robust_z = 0.6745 * (r['net'] - med) / mad
            r['robust_z'] = robust_z

    # Compute anomaly_score
    for r in filtered:
        items_eff = r['items'] if r['items'] is not None else 1
        items_eff = max(items_eff, 1)
        r['anomaly_score'] = abs(r['robust_z']) * math.log1p(items_eff)

    # Rank
    # sort by: anomaly_score desc, abs(robust_z) desc, event_time desc, record_id asc
    sorted_rows = sorted(filtered, key=lambda r: (
        -r['anomaly_score'],
        -abs(r['robust_z']),
        -r['event_time'].timestamp(),
        r['record_id']
    ))

    top_10 = [r['record_id'] for r in sorted_rows[:10]]
    return top_10


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

